/*
 * 【ことばクエスト ver1.2.1 PC｜日本語注記】
 * ファイル：scripts/3d/pc-models-inline.js
 * 役割：PCオフライン用の3Dモデル読み込みデータ（サイズが大きいため内部データは編集しない）
 * 利用画面：cat-word-puzzle.html,cat-word-race.html,PC_3D_CHECK.html
 * 注意：※ 3D埋め込みデータ：内部の長い数値・文字列は編集しないでください。
 * 変更時：読み込むHTML・service-worker.js・docs/スクリプト読込順.mdも確認してください。
 */
/* ことばクエストPC R8: オフラインでも使えるクラシックJS。元のThree.js MITライセンス素材から生成。 */
(function(){
const models={"shiba-inu.glb":"","tuxedo-cat.glb":""};
window.KQ3DModels={dog:models["shiba-inu.glb"],cat:models["tuxedo-cat.glb"]};
if(typeof window.KQGLTFLoader!=="function")throw Error("PC用3Dローダーを先に読み込んでください");
const NativeLoader=window.KQGLTFLoader;
class OfflineGLTFLoader extends NativeLoader {
  load(url,onLoad,onProgress,onError){
    const key=String(url||"").split(/[/?#]/).pop();
    const base64=models[key];
    if(!base64)return super.load(url,onLoad,onProgress,onError);
    try{
      const raw=atob(base64),bytes=new Uint8Array(raw.length);
      for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
      this.parse(bytes.buffer,"",onLoad,onError||((e)=>console.error(e)));
    }catch(error){if(onError)onError(error);else console.error(error)}
    return this;
  }
  loadAsync(url,onProgress){return new Promise((resolve,reject)=>this.load(url,resolve,onProgress,reject));}
}
window.KQGLTFLoader=OfflineGLTFLoader;
})();
